style.css:
@-moz-document domain("openai.com"), domain("chatgpt.com") {
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/jetbrainsmono/v13/tDbY2o-flEEny0FZhsfKu5WU4zr3E_BX0PnT8RD8yKxTOlOV.woff2) format('woff2');
}
body {
  background: url('https://wallpapercave.com/wp/wp13506455.jpg') no-repeat center center fixed;
  background-size: cover;
  font-family: 'Open Sans', sans-serif;
  caret-shape: block;
}

/* Container for the main chat with transparent blurred effect */
#__next > div > div.flex.h-full.flex-1.flex-col.md\:pl-\[260px\] > main > div.flex-1.overflow-hidden > div {
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  background-color: rgba(32, 33, 35, 0.3);
  padding: 40px;
  border-radius: 25px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  font-family: 'Roboto', sans-serif;
}

/* Chat messages styling */
.text-message {
  background: linear-gradient(135deg, #10a37f08, #000000);
  color: #d1d5db;
  padding: 20px;
  border-radius: 25px;
  box-shadow: 0 0 30px -15px #10a37f !important;
}

/* Chat message hover effect with glow */
.text-message:hover {
  box-shadow: inset 0 0 60px #ffffff59, inset 20px 0 80px #10a37f00, inset -20px 0 80px #00ffff47, inset 20px 0 300px #10a37f, inset -20px 0 300px #13bd94, 0 0 50px #fff, -10px 0 80px #10a37f, 10px 0 80px #0ff6;
}

/* Buttons in the chat */
button {
  backdrop-filter: blur(10px) saturate(150%);
  -webkit-backdrop-filter: blur(10px) saturate(150%);
  background-color: rgba(32, 33, 35, 0.4);
  border-radius: 25px;
  border: 1px solid rgba(54, 55, 57, 0.7);
  color: #ffffff;
  padding: 10px 15px;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
  transition: all 0.3s ease;
}

/* No padding for the specific button */
button.text-token-text-secondary {
  padding: 0 !important;
}

/* Buttons hover effect */
button:hover {
  background-color: rgba(54, 55, 57, 0.6);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.5);
}

/* Chat input box */
#__next > div > div.flex.h-full.flex-1.flex-col.md\:pl-\[260px\] > main > div.absolute.bottom-0.left-0.w-full > form > div > div.flex.flex-col.w-full {
  backdrop-filter: blur(10px) saturate(100%);
  -webkit-backdrop-filter: blur(10px) saturate(100%);
  background-color: rgba(32, 33, 35, 0.3);
  border-radius: 25px;
  border: 1px solid rgba(67, 69, 71, 0.7);
  padding: 16px;
  color: #ffffff;
}

/* Sidebar styling with auto-hide and transparent blurred effect */
#__next > div > div.dark.hidden.bg-gray-900.md\:fixed.md\:inset-y-0.md\:flex.md\:w-\[260px\].md\:flex-col {
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  background: transparent;
  width: 137px;
  border-radius: 20px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
  font-family: 'JetBrains Mono', sans-serif;
  transition: transform 0.3s ease;
  transform: translateX(-100%);
}

/* Sidebar hover to show effect */
#__next > div > div.dark.hidden.bg-gray-900.md\:fixed.md\:inset-y-0.md\:flex.md\:w-\[260px\].md\:flex-col:hover {
  transform: translateX(0);
}

/* Sidebar links with metallic shine effect */
#__next > div > div.dark.hidden.bg-gray-900.md\:fixed.md\:inset-y-0.md\:flex.md\:w-\[260px\].md\:flex-col > div > div > nav > a {
  background: linear-gradient(90deg, #ffffff, #cccccc, #ffffff);
  background-size: 200% 200%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  border-radius: 12px;
  margin-bottom: 8px;
  padding: 10px;
  transition: all 0.3s ease;
  animation: metallic-shine 5s linear infinite;
}

/* Sidebar link hover effect */
#__next > div > div.dark.hidden.bg-gray-900.md\:fixed.md\:inset-y-0.md\:flex.md\:w-\[260px\].md\:flex-col > div > div > nav > a:hover {
  background: linear-gradient(to top right, rgba(38, 198, 218, 1) 0%, rgba(156, 204, 101, 1) 50%);
  box-shadow: 0 0 15px rgba(38, 198, 218, 0.7);
}

/* Metallic shine animation */
@keyframes metallic-shine {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

/* Code blocks */
pre {
  background-color: #28292c;
  font-family: 'JetBrains Mono', monospace;
  color: #d1d5db;
  padding: 16px;
  border-radius: 25px;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.5);
}

/* General text in the chat */
.text-message,
div.flex.flex-grow.flex-col.gap-3 > div {
  color: #d1d5db;
  font-size: 16px;
}

/* Highlight text with glowing effect */
.text-gray-800.w-full.md\:max-w-2xl.lg\:max-w-3xl.md\:h-full.md\:flex.md\:flex-col.px-6.dark\:text-gray-100 {
  color: #d1d5db;
  box-shadow: inset 0 0 60px #ffffff59, 0 0 10px #ffffff87;
  filter: blur(0.5px);
}

/* Selection highlight color */
::selection {
  background: #d3d3ce2b;
}
.draggable.no-draggable-children.sticky.top-0 {
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  background-color: rgba(32, 33, 35, 0.3);
  border-bottom: 1px solid rgba(54, 55, 57, 0.5);
  z-index: 10;
  transition: background-color 0.3s ease;
}

/* Transparent and blurred sidebar surface for tokens with a bottom-right border */
.bg-token-sidebar-surface-primary {
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
  background-color: rgba(32, 33, 35, 0.3);
  transition: background-color 0.3s ease;
}
.bg-token-sidebar-surface-secondary {
  background-color: rgba(0, 0, 0, 0.16);
}
.from-token-sidebar-surface-primary {
  -tw-gradient-from: transparent var(--tw-gradient-from-position);
}
.from-token-sidebar-surface-secondary {
  -tw-gradient-from: transparent var(--tw-gradient-from-position);
}
}
